// Theme returns Entire's standard huh theme: base16 (ANSI 0–15) colors so
// form prompts respect the user's terminal palette and stay consistent with
// the rest of the CLI's styling. Derived from huh.ThemeBase16 with two
// overrides — black form titles and magenta selected options.
func Theme() huh.Theme {
	return huh.ThemeFunc(func(isDark bool) *huh.Styles {
		t := huh.ThemeBase16(isDark)

		title := lipgloss.Color(palette.Black)
		selected := lipgloss.Color(palette.Accent)

		// Black titles (Group.Title is copied from Focused.Title inside
		// ThemeBase16, so set both).
		t.Focused.Title = t.Focused.Title.Foreground(title)
		t.Group.Title = t.Group.Title.Foreground(title)

		// Magenta selected options.
		t.Focused.SelectedOption = t.Focused.SelectedOption.Foreground(selected)
		t.Focused.SelectedPrefix = t.Focused.SelectedPrefix.Foreground(selected)

		return t
	})
}

